// Confere o pedido e faz as contas. Os preços vêm SEMPRE da planilha, nunca da IA.
const entrada = $('Entrada').first().json;

function paraNumero(v) {
  if (typeof v === 'number') return v;
  if (v === null || v === undefined) return NaN;
  let s = String(v).replace(/R\$/g, '').replace(/\s/g, '');
  if (s === '') return NaN;
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  return Number(s);
}
function paraCentavos(v) { return Math.round(paraNumero(v) * 100); }
function reais(c) {
  const neg = c < 0; c = Math.abs(c);
  const inteiro = Math.floor(c / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (neg ? '-' : '') + 'R$ ' + inteiro + ',' + String(c % 100).padStart(2, '0');
}
function normalizar(s) {
  return String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
}
function simNao(v) { return normalizar(v) === 'sim'; }

// Configuração (taxa e bairros vêm da aba Configuração)
const config = {};
for (const item of $('Ler configuracao').all()) {
  config[item.json.parametro] = item.json.valor;
}
const taxaCentavos = paraCentavos(config.taxa_entrega);
const bairros = String(config.bairros_atendidos ?? '').split(',').map(b => b.trim()).filter(Boolean);

const erros = [];
if (!Number.isFinite(taxaCentavos)) erros.push('A taxa de entrega não está configurada na aba Configuração. Transfira para um atendente.');

// Produtos
const produtos = $('Ler produtos').all().map(i => i.json);
const porId = {};
const porNome = {};
for (const p of produtos) {
  porId[normalizar(p.id_produto)] = p;
  porNome[normalizar(p.nome)] = p;
}

// Itens enviados pela IA (aceita texto JSON ou lista)
let itens = entrada.itens;
if (typeof itens === 'string') {
  try { itens = JSON.parse(itens); } catch (e) { itens = null; }
}
if (itens && !Array.isArray(itens) && typeof itens === 'object') itens = [itens];
if (!Array.isArray(itens) || itens.length === 0) {
  erros.push('Nenhum item válido foi enviado. Envie os itens como [{"id_produto": "P0001", "quantidade": 2}].');
  itens = [];
}

const linhas = [];
const somaPorProduto = {};
for (const it of itens) {
  const chaveId = normalizar(it.id_produto ?? it.id ?? it.codigo);
  const chaveNome = normalizar(it.nome ?? it.produto);
  const p = porId[chaveId] || porNome[chaveNome] || porNome[chaveId];
  const quantidade = Number(it.quantidade ?? it.qtd ?? 1);
  const rotulo = it.id_produto || it.nome || it.produto || '(sem nome)';
  if (!p) { erros.push(`Produto "${rotulo}" não encontrado no catálogo. Use consultar_produtos para pegar o id_produto certo.`); continue; }
  if (!Number.isInteger(quantidade) || quantidade < 1) { erros.push(`Quantidade inválida para ${p.nome}.`); continue; }
  if (!simNao(p.ativo)) { erros.push(`${p.nome} não está disponível para venda.`); continue; }
  if (simNao(p.exige_receita) || simNao(p.controlado)) {
    erros.push(`${p.nome} exige receita${simNao(p.controlado) ? ' e é controlado' : ''}. Este item não pode ser registrado por aqui: peça a foto da receita e use transferir_farmaceutico.`);
    continue;
  }
  const precoCentavos = paraCentavos(p.preco);
  if (!Number.isFinite(precoCentavos) || precoCentavos <= 0) { erros.push(`${p.nome} está sem preço no catálogo. Transfira para um atendente.`); continue; }
  somaPorProduto[p.id_produto] = (somaPorProduto[p.id_produto] || 0) + quantidade;
  const estoque = paraNumero(p.estoque_atual);
  if (!Number.isFinite(estoque) || somaPorProduto[p.id_produto] > estoque) {
    erros.push(`Estoque insuficiente de ${p.nome}: o cliente pediu ${somaPorProduto[p.id_produto]} e temos ${Number.isFinite(estoque) ? estoque : 0}.`);
    continue;
  }
  linhas.push({
    id_produto: p.id_produto,
    produto: p.nome,
    apresentacao: p.apresentacao,
    quantidade,
    preco_centavos: precoCentavos,
    subtotal_centavos: precoCentavos * quantidade,
  });
}

// Cliente (pelo telefone que veio do sistema, nunca da conversa)
const cliente = $('Ler cliente').all().map(i => i.json).find(c => c && c.telefone !== undefined && String(c.telefone).trim() !== '');
if (!cliente) {
  erros.push('O cliente ainda não tem cadastro. Peça nome, endereço, número, bairro e ponto de referência e use salvar_cliente antes.');
} else if (!bairros.includes(String(cliente.bairro).trim())) {
  erros.push(`O bairro cadastrado (${cliente.bairro}) está fora da área de entrega (${bairros.join(' e ')}).`);
}

// Pagamento
const formas = { pix: 'Pix', cartao: 'Cartão na entrega', 'cartao na entrega': 'Cartão na entrega', credito: 'Cartão na entrega', debito: 'Cartão na entrega', dinheiro: 'Dinheiro' };
let forma = formas[normalizar(entrada.forma_pagamento)];
if (!forma && normalizar(entrada.forma_pagamento).startsWith('cart')) forma = 'Cartão na entrega';
if (!forma) erros.push('Forma de pagamento inválida. Use Pix, Cartão na entrega ou Dinheiro.');

const subtotal = linhas.reduce((s, l) => s + l.subtotal_centavos, 0);
const total = subtotal + (Number.isFinite(taxaCentavos) ? taxaCentavos : 0);

let trocoCentavos = null;
if (forma === 'Dinheiro') {
  const t = paraCentavos(entrada.troco_para);
  if (Number.isFinite(t) && t > 0) {
    if (t < total) erros.push(`O troco informado (${reais(t)}) é menor que o total do pedido (${reais(total)}). Pergunte de novo para quanto o cliente precisa de troco.`);
    else trocoCentavos = t;
  }
}

const confirmado = entrada.confirmado === true || normalizar(entrada.confirmado) === 'true' || normalizar(entrada.confirmado) === 'sim';

let enderecoEntrega = '';
if (cliente) {
  enderecoEntrega = [cliente.endereco, cliente.numero, cliente.complemento].map(x => String(x ?? '').trim()).filter(Boolean).join(', ');
}

let mensagem;
if (erros.length > 0) {
  mensagem = 'PEDIDO NÃO REGISTRADO. Problemas encontrados:\n- ' + erros.join('\n- ') + '\nExplique ao cliente com gentileza e resolva antes de tentar de novo.';
} else {
  const textoItens = linhas.map(l => `${l.quantidade}x ${l.produto} (${l.apresentacao}): ${reais(l.subtotal_centavos)}`).join('\n');
  const partes = [
    `Itens:\n${textoItens}`,
    `Subtotal: ${reais(subtotal)}`,
    `Taxa de entrega: ${reais(taxaCentavos)}`,
    `Total: ${reais(total)}`,
    `Pagamento: ${forma}${trocoCentavos !== null ? ` (troco para ${reais(trocoCentavos)}: levar ${reais(trocoCentavos - total)} de troco)` : ''}`,
    `Entrega em: ${enderecoEntrega}, ${cliente.bairro}${cliente.ponto_referencia ? ` (referência: ${cliente.ponto_referencia})` : ''}`,
  ];
  if (confirmado) {
    mensagem = 'GRAVANDO PEDIDO.\n' + partes.join('\n');
  } else {
    mensagem = 'RESUMO CALCULADO PELO SISTEMA (o pedido ainda NÃO foi gravado).\n' + partes.join('\n') +
      '\nMostre este resumo ao cliente usando exatamente estes valores e peça confirmação. Só depois do "sim" chame registrar_pedido de novo, com os mesmos itens e confirmado = true.';
  }
}

return [{
  json: {
    gravar: erros.length === 0 && confirmado,
    mensagem,
    erros,
    itens: linhas,
    subtotal_centavos: subtotal,
    taxa_centavos: taxaCentavos,
    total_centavos: total,
    forma_pagamento: forma || '',
    troco_centavos: trocoCentavos,
    telefone: entrada.telefone,
    nome_cliente: cliente ? cliente.nome : '',
    endereco_entrega: enderecoEntrega,
    bairro: cliente ? cliente.bairro : '',
    observacoes: String(entrada.observacoes ?? '').trim(),
  }
}];

// Gera o número do pedido e monta as linhas para as abas Pedidos, Itens_Pedidos e Pagamentos.
const c = $('Calcular pedido').first().json;

let maior = 0;
for (const item of $('Ler pedidos').all()) {
  const m = /^PED-(\d+)$/.exec(String(item.json.id_pedido ?? '').trim());
  if (m) maior = Math.max(maior, Number(m[1]));
}
const numero = String(maior + 1).padStart(4, '0');
const idPedido = 'PED-' + numero;
const idPagamento = 'PAG-' + numero;
const dataHora = $now.setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy HH:mm:ss');

// Valores em texto com vírgula: a planilha (português) entende como número.
function valor(c) { return (c / 100).toFixed(2).replace('.', ','); }

return [{
  json: {
    id_pedido: idPedido,
    id_pagamento: idPagamento,
    pedido: {
      id_pedido: idPedido,
      data_hora: dataHora,
      telefone_cliente: "'" + c.telefone,
      nome_cliente: c.nome_cliente,
      endereco_entrega: c.endereco_entrega,
      bairro: c.bairro,
      subtotal: valor(c.subtotal_centavos),
      taxa_entrega: valor(c.taxa_centavos),
      total: valor(c.total_centavos),
      forma_pagamento: c.forma_pagamento,
      troco_para: c.troco_centavos !== null ? valor(c.troco_centavos) : '',
      status: 'Novo',
      atendido_por: 'IA',
      observacoes: c.observacoes,
    },
    itens: c.itens.map(l => ({
      id_pedido: idPedido,
      id_produto: l.id_produto,
      produto: l.produto,
      quantidade: l.quantidade,
      preco_unitario: valor(l.preco_centavos),
      subtotal_item: valor(l.subtotal_centavos),
    })),
    pagamento: {
      id_pagamento: idPagamento,
      id_pedido: idPedido,
      data_hora: dataHora,
      forma_pagamento: c.forma_pagamento,
      valor: valor(c.total_centavos),
      status: 'Pendente',
      conferido_por: '',
      comprovante: '',
    },
  }
}];

const p = $('Preparar gravacao').first().json;
const c = $('Calcular pedido').first().json;
const resumo = c.mensagem.replace('GRAVANDO PEDIDO.\n', '');
return [{ json: { resposta:
  `PEDIDO REGISTRADO COM SUCESSO. Número do pedido: ${p.id_pedido}.\n${resumo}\n` +
  `Informe ao cliente o número ${p.id_pedido} e o total. Depois use acionar_entrega com id_pedido = ${p.id_pedido}. ` +
  `Não chame registrar_pedido de novo para este pedido.`
} }];
